vista.lang:
root Stack direction=vertical > ver,resumen,detalle
ver Select "Ver" name=vista options=[{"value":"resumen","label":"Resumen"},{"value":"detalle","label":"Detalle"}]
resumen Grid columns=3 si={"$":"vista","es":"resumen"} > s_sub,s_baj,s_igu
s_sub Stat "Subieron" icon=subio query={"tipo":"totales","campo":"subieron"}
s_baj Stat "Bajaron" icon=bajo query={"tipo":"totales","campo":"bajaron"}
s_igu Stat "Iguales" icon=igual query={"tipo":"totales","campo":"iguales"}
detalle Stack si={"$":"vista","es":"detalle"} > tabla,grafico
